import { test, expect } from '@playwright/test';

test.describe('Table Row Selection Highlighting', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/table-list');
  });

  test('should highlight selected table rows with a different background color', async ({ page }) => {
    // Verify table is visible
    const table = page.getByRole('table');
    await expect(table).toBeVisible();

    // Verify table header is visible
    const header = page.getByRole('columnheader', { name: 'Name' });
    await expect(header).toBeVisible();

    // Select the first row by clicking the checkbox
    const firstRowCheckbox = page.getByRole('checkbox', { name: 'Select row 1' });
    await firstRowCheckbox.click();

    // Verify the first row is highlighted
    const firstRow = page.locator('[data-testid="table-row-1"]');
    await expect(firstRow).toHaveClass(/selected-row/);

    // Verify the background color is applied
    const firstRowBg = await firstRow.evaluate((el) => window.getComputedStyle(el).backgroundColor);
    expect(firstRowBg).not.toBe('rgba(0, 0, 0, 0)');

    // Select the third row
    const thirdRowCheckbox = page.getByRole('checkbox', { name: 'Select row 3' });
    await thirdRowCheckbox.click();

    // Verify the third row is highlighted
    const thirdRow = page.locator('[data-testid="table-row-3"]');
    await expect(thirdRow).toHaveClass(/selected-row/);

    // Verify both rows are highlighted
    const allSelectedRows = page.locator('[data-testid="table-row-1"], [data-testid="table-row-3"]');
    await expect(allSelectedRows).toHaveClass(/selected-row/);

    // Verify the selection count is updated
    const selectionCount = page.getByText('2 selected');
    await expect(selectionCount).toBeVisible();
  });

  test('should unhighlight a row when selection is deselected', async ({ page }) => {
    // Select the second row
    const secondRowCheckbox = page.getByRole('checkbox', { name: 'Select row 2' });
    await secondRowCheckbox.click();

    // Verify the second row is highlighted
    const secondRow = page.locator('[data-testid="table-row-2"]');
    await expect(secondRow).toHaveClass(/selected-row/);

    // Verify the selection count is updated
    const selectionCount = page.getByText('1 selected');
    await expect(selectionCount).toBeVisible();

    // Deselect the second row
    await secondRowCheckbox.click();

    // Verify the second row is no longer highlighted
    await expect(secondRow).not.toHaveClass(/selected-row/);

    // Verify the selection count is reset
    const noSelectionText = page.getByText('No rows selected');
    await expect(noSelectionText).toBeVisible();
  });
});
